async function run() {
  const nowIso = now();
  const todayPart = nowIso.slice(0, 10);
  const [ty, tm, td] = todayPart.split('-').map(Number);
  const todayUTC = Date.UTC(ty, tm - 1, td);
  const horizonUTC = todayUTC + 7 * 24 * 60 * 60 * 1000;

  const emails = await gmail.search({
    query: "boleto OR fatura OR invoice OR vencimento",
    days: 30,
    max: 30
  });

  const candidates = [];
  for (const e of emails) {
    const text = `${e.subject} ${e.snippet}`;
    const dateMatch = text.match(/(\d{2})\/(\d{2})\/(\d{4})/);
    const amountMatch = text.match(/R\$\s?\d{1,3}(?:\.\d{3})*(?:,\d{2})?/);
    if (!dateMatch || !amountMatch) continue;

    const [, d, m, y] = dateMatch;
    const dueUTC = Date.UTC(Number(y), Number(m) - 1, Number(d));
    if (dueUTC < todayUTC || dueUTC > horizonUTC) continue;

    const amountStr = amountMatch[0].trim();
    const numeric = parseFloat(
      amountStr.replace('R$', '').trim().replace(/\./g, '').replace(',', '.')
    );

    candidates.push({ email: e, dueUTC, dueLabel: `${d}/${m}`, amountStr, numeric });
  }

  const pending = [];
  for (const c of candidates) {
    const { p } = await judge.isPendingBill(c.email);
    if (p >= 0.5) pending.push(c);
  }

  if (pending.length === 0) {
    log('Nenhuma conta pendente vencendo nos próximos 7 dias.');
    return;
  }

  pending.sort((a, b) => a.dueUTC - b.dueUTC);

  let total = 0;
  const lines = pending.map((c) => {
    total += Number.isFinite(c.numeric) ? c.numeric : 0;
    const label = c.email.from_name || c.email.subject;
    return `• ${c.dueLabel} — ${label}: ${c.amountStr}`;
  });

  const totalFormatted =
    'R$ ' +
    total
      .toFixed(2)
      .replace('.', ',')
      .replace(/\B(?=(\d{3})+(?=,))/g, '.');

  const text = `Contas vencendo nos próximos 7 dias:\n\n${lines.join('\n')}\n\nTotal: ${totalFormatted}`;

  await telegram.send({ text });
}

async function run() {
  const emails = await gmail.search({ query: "boleto OR fatura OR invoice OR vencimento", days: 30, max: 30 });

  if (!emails || emails.length === 0) {
    log("Nenhum e-mail encontrado.");
    return;
  }

  const nowDate = new Date(now());
  const startOfToday = new Date(nowDate.getFullYear(), nowDate.getMonth(), nowDate.getDate());
  const endWindow = new Date(startOfToday);
  endWindow.setDate(endWindow.getDate() + 7);

  function extractAmount(text) {
    const m = text.match(/R\$\s?([\d.,]+)/);
    return m ? m[1] : null;
  }

  function extractDueDate(text) {
    const matches = [...text.matchAll(/(\d{2})\/(\d{2})\/(\d{4})/g)];
    if (matches.length === 0) return null;
    const last = matches[matches.length - 1];
    const day = parseInt(last[1], 10);
    const month = parseInt(last[2], 10) - 1;
    const year = parseInt(last[3], 10);
    return new Date(year, month, day);
  }

  function parseAmountValue(str) {
    return parseFloat(str.replace(/\./g, "").replace(",", "."));
  }

  function formatBRL(num) {
    return num.toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }

  function fmtDate(d) {
    const dd = String(d.getDate()).padStart(2, "0");
    const mm = String(d.getMonth() + 1).padStart(2, "0");
    return `${dd}/${mm}`;
  }

  const candidates = [];

  for (const item of emails) {
    const text = `${item.subject || ""} ${item.snippet || ""}`;
    const dueDate = extractDueDate(text);
    const amountStr = extractAmount(text);
    if (!dueDate || !amountStr) continue;
    if (dueDate < startOfToday || dueDate > endWindow) continue;

    const judgment = await judge.isPendingBill(item);
    if (judgment.p < 0.5) continue;

    candidates.push({
      item,
      dueDate,
      amountStr,
      amountValue: parseAmountValue(amountStr),
    });
  }

  if (candidates.length === 0) {
    log("Nenhuma conta pendente vencendo nos próximos 7 dias.");
    return;
  }

  candidates.sort((a, b) => a.dueDate - b.dueDate);

  let total = 0;
  const lines = candidates.map((c) => {
    total += c.amountValue;
    const label = c.item.from_name || c.item.from || "Conta";
    return `• ${fmtDate(c.dueDate)} — ${label}: R$ ${c.amountStr}`;
  });

  const text =
    `Contas vencendo nos próximos 7 dias:\n\n` +
    lines.join("\n") +
    `\n\nTotal: R$ ${formatBRL(total)}`;

  await telegram.send({ text });
}

async function run() {
  const emails = await gmail.search({ query: "in:inbox is:unread", days: 2, unread: true, max: 50 });

  const archived = [];
  for (const e of emails) {
    const { p } = await judge.newsletter(e);
    if (p >= 0.5) {
      await gmail.archive({ id: e.id });
      archived.push(e);
    }
  }

  const count = archived.length;
  let text;
  if (count === 0) {
    text = "Inbox cleanup: no newsletters or promos to archive.";
  } else {
    const names = archived.map(e => e.from_name || e.from).join(", ");
    const noun = count === 1 ? "newsletter/promo" : "newsletters/promos";
    text = `Inbox cleanup done: archived ${count} ${noun} (${names}).`;
  }

  log(`Archived ${count} of ${emails.length} unread inbox emails.`);
  await telegram.send({ text });
}

