async function run() {
  const BOSS_EMAIL = "ana@acme.com";
  const NOTIFIED_LABEL = "vigia-ana-notificado";

  const query = `in:inbox is:unread from:${BOSS_EMAIL} -label:${NOTIFIED_LABEL}`;
  const emails = await gmail.search({ query, days: 1, unread: true, max: 20 });

  for (const email of emails) {
    // segurança extra: garante que é mesmo a chefe, ignora qualquer outro remetente
    if (!email.from || email.from.toLowerCase() !== BOSS_EMAIL) continue;

    const nome = email.from_name || BOSS_EMAIL;
    const trecho = email.snippet ? `\n${email.snippet}` : "";
    const text = `📩 Email da ${nome}: "${email.subject}"${trecho}`;

    await telegram.send({ text });
    // marca para não notificar de novo no próximo agendamento
    await gmail.label({ id: email.id, label: NOTIFIED_LABEL });

    log(`Alerta enviado para email ${email.id} da Ana`);
  }

  if (emails.length === 0) {
    log("Nenhum email novo não lido da Ana.");
  }
}

async function run() {
  const nowStr = now();
  const offsetMatch = nowStr.match(/(Z|[+-]\d{2}:\d{2})$/);
  const offset = offsetMatch ? (offsetMatch[1] === 'Z' ? '+00:00' : offsetMatch[1]) : '+00:00';

  // Date part of "now", used as the anchor for building the 7-day window.
  const todayDatePart = nowStr.slice(0, 10); // YYYY-MM-DD
  const startBase = new Date(todayDatePart + 'T00:00:00Z');
  startBase.setUTCDate(startBase.getUTCDate() + 1); // tomorrow = start of the coming week

  const days = [];
  for (let i = 0; i < 7; i++) {
    const d = new Date(startBase.getTime());
    d.setUTCDate(d.getUTCDate() + i);
    days.push(d);
  }

  const pad = n => String(n).padStart(2, '0');
  const dateKey = d => `${d.getUTCFullYear()}-${pad(d.getUTCMonth() + 1)}-${pad(d.getUTCDate())}`;
  const weekdayNames = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

  const from = `${dateKey(days[0])}T00:00:00${offset}`;
  const to = `${dateKey(days[6])}T23:59:59${offset}`;

  log(`Fetching agenda from ${from} to ${to}`);
  const events = await calendar.events({ from, to });

  const buckets = {};
  for (const d of days) buckets[dateKey(d)] = [];

  for (const ev of events) {
    const key = ev.start.slice(0, 10);
    if (buckets[key]) {
      buckets[key].push(ev);
    }
  }

  for (const key in buckets) {
    buckets[key].sort((a, b) => a.start.localeCompare(b.start));
  }

  const lines = ['Your week ahead:'];
  for (const d of days) {
    const key = dateKey(d);
    const label = `${weekdayNames[d.getUTCDay()]} ${pad(d.getUTCDate())}/${pad(d.getUTCMonth() + 1)}`;
    const dayEvents = buckets[key];
    let block = label + '\n';
    if (dayEvents.length === 0) {
      block += '• nothing scheduled';
    } else {
      block += dayEvents.map(ev => `• ${ev.start.slice(11, 16)} ${ev.title}`).join('\n');
    }
    lines.push(block);
  }

  const text = lines.join('\n\n');
  await telegram.send({ text });
  log('Sent weekly agenda to Telegram');
}

async function run() {
  function parseOffset(iso) {
    const m = iso.match(/([+-]\d{2}:\d{2}|Z)$/);
    if (!m || m[1] === 'Z') return '+00:00';
    return m[1];
  }
  function offsetMs(offset) {
    const sign = offset[0] === '-' ? -1 : 1;
    const [oh, om] = offset.slice(1).split(':').map(Number);
    return sign * (oh * 60 + om) * 60000;
  }
  function shifted(date, offMs) {
    return new Date(date.getTime() + offMs);
  }
  function pad(n) { return String(n).padStart(2, '0'); }

  const nowIso = now();
  const offset = parseOffset(nowIso);
  const offMs = offsetMs(offset);
  const nowDate = new Date(nowIso);
  const tomorrowShiftedUTC = shifted(new Date(nowDate.getTime() + 24 * 60 * 60 * 1000), offMs);
  const y = tomorrowShiftedUTC.getUTCFullYear();
  const mo = tomorrowShiftedUTC.getUTCMonth() + 1;
  const d = tomorrowShiftedUTC.getUTCDate();
  const dateStr = `${y}-${pad(mo)}-${pad(d)}`;
  const from = `${dateStr}T00:00:00${offset}`;
  const to = `${dateStr}T23:59:59${offset}`;

  log(`Buscando reuniões de amanhã (${dateStr}) entre ${from} e ${to}`);

  const events = await calendar.events({ from, to });
  const meetings = (events || []).filter(e => Array.isArray(e.attendees) && e.attendees.length > 0);

  if (meetings.length === 0) {
    log('Nenhuma reunião com convidados amanhã. Nada a enviar.');
    return;
  }

  function formatTime(iso) {
    const dt = shifted(new Date(iso), offMs);
    return `${pad(dt.getUTCHours())}:${pad(dt.getUTCMinutes())}`;
  }

  // Cache de buscas por email para evitar repetir a mesma busca
  const emailCache = new Map();
  for (const meeting of meetings) {
    for (const attendee of meeting.attendees) {
      if (!emailCache.has(attendee)) {
        const results = await gmail.search({ query: `from:${attendee}`, days: 14, max: 5 });
        emailCache.set(attendee, results || []);
      }
    }
  }

  const sections = [];
  for (const meeting of meetings) {
    const lines = [];
    for (const attendee of meeting.attendees) {
      const msgs = emailCache.get(attendee) || [];
      if (msgs.length === 0) continue;
      const name = msgs[0].from_name || attendee;
      for (const msg of msgs) {
        const status = msg.replied ? '' : ' (sem resposta)';
        lines.push(`• ${name} — "${msg.subject}"${status}`);
      }
    }
    if (lines.length > 0) {
      sections.push(`${formatTime(meeting.start)} ${meeting.title}\n${lines.join('\n')}`);
    } else {
      sections.push(`${formatTime(meeting.start)} ${meeting.title}\n(sem emails recentes dos convidados)`);
    }
  }

  const [yy, mm, dd] = dateStr.split('-');
  const header = `Preparação para amanhã (${dd}/${mm})`;
  const text = `${header}\n\n${sections.join('\n\n')}`;

  await telegram.send({ text });
}

async function run() {
  const OFFSET_HOURS = -3; // America/Sao_Paulo, mesmo offset usado na gravação original
  const offsetMs = OFFSET_HOURS * 60 * 60 * 1000;
  const offsetStr = (OFFSET_HOURS <= 0 ? '-' : '+') + String(Math.abs(OFFSET_HOURS)).padStart(2, '0') + ':00';

  const nowDate = new Date(now());
  const localNow = new Date(nowDate.getTime() + offsetMs);
  const localTomorrow = new Date(localNow.getTime() + 24 * 60 * 60 * 1000);

  const y = localTomorrow.getUTCFullYear();
  const m = String(localTomorrow.getUTCMonth() + 1).padStart(2, '0');
  const d = String(localTomorrow.getUTCDate()).padStart(2, '0');

  const from = `${y}-${m}-${d}T00:00:00${offsetStr}`;
  const to = `${y}-${m}-${d}T23:59:59${offsetStr}`;

  const events = await calendar.events({ from, to });
  const meetings = (events || []).filter(e => Array.isArray(e.attendees) && e.attendees.length > 0);

  if (meetings.length === 0) {
    log("Nenhuma reunião com convidados amanhã. Nada a enviar.");
    return;
  }

  const emailCache = new Map();

  async function getEmailsFor(address) {
    if (emailCache.has(address)) return emailCache.get(address);
    const results = await gmail.search({ query: `from:${address}`, days: 14, max: 5 });
    emailCache.set(address, results || []);
    return emailCache.get(address);
  }

  const blocks = [];
  for (const meeting of meetings) {
    const startDate = new Date(meeting.start);
    const localStart = new Date(startDate.getTime() + offsetMs);
    const hh = String(localStart.getUTCHours()).padStart(2, '0');
    const mm = String(localStart.getUTCMinutes()).padStart(2, '0');

    const lines = [`${hh}:${mm} ${meeting.title}`];

    const seenInMeeting = new Set();
    for (const address of meeting.attendees) {
      if (seenInMeeting.has(address)) continue;
      seenInMeeting.add(address);

      const emails = await getEmailsFor(address);
      const name = emails.length > 0 ? (emails[0].from_name || address) : address;

      if (emails.length === 0) {
        lines.push(`• ${name} — (sem emails recentes dos convidados)`);
      } else {
        const subjects = emails.map(e => e.replied ? e.subject : `${e.subject} (sem resposta)`);
        lines.push(`• ${name} — ${subjects.join('; ')}`);
      }
    }

    blocks.push(lines.join('\n'));
  }

  const header = `Preparação para amanhã (${d}/${m})`;
  const text = `${header}\n\n${blocks.join('\n\n')}`;

  await telegram.send({ text });
}

async function run() {
  const threshold = 5.40;
  const url = "https://api.exchangerate.example/v1/latest?base=USD&symbols=BRL";
  const data = await http.getJSON(url);

  const rate = data && data.rates && data.rates.BRL;
  if (typeof rate !== "number") {
    log("No USD->BRL rate found in response; skipping.");
    return;
  }

  log("USD->BRL rate: " + rate);

  if (rate > threshold) {
    const text = "💵 USD→BRL is at " + rate.toFixed(2) + ", above your " + threshold.toFixed(2) + " threshold.";
    await telegram.send({ text });
  } else {
    log("Rate " + rate + " is at or below threshold " + threshold + "; no alert sent.");
  }
}

async function run() {
  const nowDate = new Date(now());
  const THRESHOLD_MS = 3 * 24 * 60 * 60 * 1000;

  const emails = await gmail.search({ query: "in:inbox -from:me", days: 30, max: 50 });

  const candidates = [];
  for (const e of emails) {
    if (e.replied) continue;

    const emailDate = new Date(e.date);
    const ageMs = nowDate - emailDate;
    if (ageMs < THRESHOLD_MS) continue;

    const { p } = await judge.needs_reply(e);
    if (p >= 0.5) {
      candidates.push(e);
    }
  }

  if (candidates.length === 0) {
    log("No emails waiting on reply for more than 3 days.");
    return;
  }

  candidates.sort((a, b) => new Date(a.date) - new Date(b.date));

  const lines = candidates.map((e) => {
    const d = new Date(e.date);
    const dateStr = d.toLocaleDateString("en-US", { month: "short", day: "numeric" });
    const who = e.from_name || e.from;
    return `• ${who} — "${e.subject}" (since ${dateStr})`;
  });

  const text = `Waiting on your reply (3+ days):\n\n${lines.join("\n")}`;
  await telegram.send({ text });
}

async function run() {
  const nowIso = now();
  const offsetMatch = nowIso.match(/([+-]\d{2}:\d{2}|Z)$/);
  const offset = offsetMatch ? offsetMatch[0] : "Z";
  const todayStr = nowIso.slice(0, 10);

  function addDays(dateStr, n) {
    const [y, m, d] = dateStr.split("-").map(Number);
    const dt = new Date(Date.UTC(y, m - 1, d));
    dt.setUTCDate(dt.getUTCDate() + n);
    const yyyy = dt.getUTCFullYear();
    const mm = String(dt.getUTCMonth() + 1).padStart(2, "0");
    const dd = String(dt.getUTCDate()).padStart(2, "0");
    return `${yyyy}-${mm}-${dd}`;
  }

  const tomorrowStr = addDays(todayStr, 1);
  const from = `${todayStr}T00:00:00${offset}`;
  const to = `${tomorrowStr}T23:59:59${offset}`;

  const events = await calendar.events({ from, to });

  const BIRTHDAY_CALENDAR = "Birthdays";
  const birthdays = events.filter(
    (e) => (e.calendar || "").toLowerCase() === BIRTHDAY_CALENDAR.toLowerCase()
  );

  const todayList = [];
  const tomorrowList = [];
  for (const e of birthdays) {
    const startDate = (e.start || "").slice(0, 10);
    if (startDate === todayStr) todayList.push(e.title);
    else if (startDate === tomorrowStr) tomorrowList.push(e.title);
  }

  if (todayList.length === 0 && tomorrowList.length === 0) {
    log("Nenhum aniversário hoje ou amanhã.");
    return;
  }

  function fmtDM(dateStr) {
    const parts = dateStr.split("-");
    return `${parts[2]}/${parts[1]}`;
  }

  const lines = ["🎂 Aniversários", ""];
  if (todayList.length > 0) {
    lines.push(`Hoje (${fmtDM(todayStr)}): ${todayList.join(", ")}`);
  }
  if (tomorrowList.length > 0) {
    lines.push(`Amanhã (${fmtDM(tomorrowStr)}): ${tomorrowList.join(", ")}`);
  }

  await telegram.send({ text: lines.join("\n") });
}
